/* Host tests for fact parsing and rule decisions. Needs BB_FIXTURES (private
 * dumps: <board>-art.bin, <board>-cdt.bin, field-env.bin) and BB_RULES (a rule
 * file generated by pack/make_rules.py from the U-Boot release). */
#include "../runtime/rules.h"

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static int failures, checks;
static const char *fixtures;

#define CHECK(cond, ...) do { \
	checks++; \
	if (!(cond)) { \
		failures++; \
		printf("FAIL %s:%d: ", __FILE__, __LINE__); \
		printf(__VA_ARGS__); \
		printf("\n"); \
	} \
} while (0)

static uint8_t *load(const char *path, size_t *len)
{
	FILE *f = fopen(path, "rb");
	uint8_t *buf;
	long n;

	if (!f)
		return NULL;
	fseek(f, 0, SEEK_END);
	n = ftell(f);
	rewind(f);
	buf = malloc(n + 1);
	if (buf && fread(buf, 1, n, f) != (size_t)n) {
		free(buf);
		buf = NULL;
	}
	fclose(f);
	if (buf) {
		buf[n] = 0;
		*len = n;
	}
	return buf;
}

static uint8_t *fixture(const char *name, size_t *len)
{
	char path[512];

	snprintf(path, sizeof(path), "%s/%s", fixtures, name);
	return load(path, len);
}

/* The NAND lines an OEM 4.4 kernel prints (format from real boot logs). */
static const char kmsg_gd_ecc8[] =
	"[    1.0] nand: device found, Manufacturer ID: 0xc8, Chip ID: 0x41\n"
	"[    1.0] nand: ESMT GD5F1GQ5REYIG SPI NAND 1G\n"
	"[    1.0] nand: 128 MiB, SLC, erase size: 128 KiB, page size: 2048, OOB size: 128\n";
static const char kmsg_w25n[] =
	"[    1.005766] nand: device found, Manufacturer ID: 0xef, Chip ID: 0xba\n"
	"[    1.010229] nand: Winbond W25N01GWZEIG SPI NAND 1.8V 1G-BIT\n"
	"[    1.016602] nand: 128 MiB, SLC, erase size: 128 KiB, page size: 2048, OOB size: 64\n";

struct sample {
	const char *name;	/* fixture prefix */
	const char *model;	/* device tree model */
	const char *kmsg;
	unsigned ecc;
	int has_cdt;
	const char *want_board;
	const char *want_cand;
};

static const struct sample samples[] = {
	{ "hwa", "Qualcomm Technologies, Inc. IPQ5018/AP-MP03.1", kmsg_w25n, 4, 1, "A",
	  "A-h3c-oem-efba-128m-2k-sp64-ecc4" },
	{ "hwb", "Qualcomm Technologies, Inc. IPQ5018/AP-MP02.1", kmsg_gd_ecc8, 8, 1, "B",
	  "B-h3c-oem-c841-128m-2k-sp128-ecc8" },
	{ "hwc", "Qualcomm Technologies, Inc. IPQ5018/AP-MP03.1-C2", kmsg_w25n, 4, 1, "C",
	  "C-h3c-oem-efba-128m-2k-sp64-ecc4" },
	{ "hwd", "Qualcomm Technologies, Inc. IPQ5018/AP-MP02.1", kmsg_w25n, 4, 1, "D",
	  "D-h3c-oem-efba-128m-2k-sp64-ecc4" },
	{ "field", "Qualcomm Technologies, Inc. IPQ5018/AP-MP02.1", kmsg_gd_ecc8, 8, 1, "B",
	  "B-h3c-oem-c841-128m-2k-sp128-ecc8" },
	/* FEM-less HW-D: decided as HW-B on purpose. No CDT dump, machid set by hand. */
	{ "rc3000b0", "Qualcomm Technologies, Inc. IPQ5018/AP-MP02.1", kmsg_gd_ecc8, 8, 0, "B",
	  "B-h3c-oem-c841-128m-2k-sp128-ecc8" },
};

static int build(const struct sample *s, struct bb_facts *f)
{
	char name[64];
	uint8_t *buf;
	size_t len;

	memset(f, 0, sizeof(*f));
	bb_facts_parse_dt_model(f, s->model);
	bb_facts_parse_kmsg(f, s->kmsg);
	f->mtd_ecc_strength = s->ecc;
	snprintf(name, sizeof(name), "%s-art.bin", s->name);
	buf = fixture(name, &len);
	if (!buf)
		return -1;
	/* The raw B0 dump has one flipped bit in the first byte; ECC would fix it. */
	if (!strcmp(s->name, "rc3000b0"))
		buf[0x26800] &= 0x7f;
	bb_facts_parse_art(f, buf, len);
	free(buf);
	if (s->has_cdt) {
		snprintf(name, sizeof(name), "%s-cdt.bin", s->name);
		buf = fixture(name, &len);
		if (!buf || bb_facts_parse_cdt(f, buf, len)) {
			free(buf);
			return -1;
		}
		free(buf);
	} else {
		f->machid = 0x08040000;
		f->have_machid = 1;
	}
	return 0;
}

static void test_samples(const struct bb_rules *r)
{
	for (size_t i = 0; i < sizeof(samples) / sizeof(samples[0]); i++) {
		const struct sample *s = &samples[i];
		struct bb_decision d;
		struct bb_facts f;

		if (build(s, &f)) {
			CHECK(0, "%s: fixtures missing", s->name);
			continue;
		}
		bb_rules_decide(r, &f, &d);
		CHECK(d.code == BB_DEC_OK, "%s: %s (%s)", s->name, bb_decide_str(d.code), d.detail);
		CHECK(!strcmp(d.board, s->want_board), "%s: board %s want %s", s->name, d.board,
		      s->want_board);
		CHECK(d.cand && !strcmp(d.cand->id, s->want_cand), "%s: candidate %s want %s", s->name,
		      d.cand ? d.cand->id : "-", s->want_cand);
	}
}

static void test_refusals(const struct bb_rules *r)
{
	struct bb_decision d;
	struct bb_facts f, base;

	if (build(&samples[1], &base))
		return;

	f = base;	/* calibration block from neither known design */
	f.art5g[0x3a] = 0x55;
	bb_rules_decide(r, &f, &d);
	CHECK(d.code == BB_DEC_NO_BOARD, "unknown art: %s", bb_decide_str(d.code));

	f = base;	/* no ART at all */
	f.have_art5g = 0;
	bb_rules_decide(r, &f, &d);
	CHECK(d.code == BB_DEC_NO_BOARD, "missing art: %s", bb_decide_str(d.code));

	f = base;	/* route and CDT disagree */
	f.machid = 0x08040001;
	bb_rules_decide(r, &f, &d);
	CHECK(d.code == BB_DEC_NO_BOARD, "route/cdt mismatch: %s", bb_decide_str(d.code));

	f = base;
	f.have_route = 0;
	bb_rules_decide(r, &f, &d);
	CHECK(d.code == BB_DEC_NO_BOARD, "no route: %s", bb_decide_str(d.code));

	f = base;	/* NAND not in the catalog */
	f.nand_chip = 0x99;
	bb_rules_decide(r, &f, &d);
	CHECK(d.code == BB_DEC_NO_NAND, "unknown nand: %s", bb_decide_str(d.code));

	f = base;	/* model string differs: never guess from the ID alone */
	snprintf(f.nand_model, sizeof(f.nand_model), "GD5F1GQ5REYIX");
	bb_rules_decide(r, &f, &d);
	CHECK(d.code == BB_DEC_NO_NAND, "model mismatch: %s", bb_decide_str(d.code));

	f = base;	/* no candidate for this ECC */
	f.mtd_ecc_strength = 6;
	bb_rules_decide(r, &f, &d);
	CHECK(d.code == BB_DEC_NO_CANDIDATE, "ecc 6: %s", bb_decide_str(d.code));
}

static void test_ambiguity(void)
{
	static const char *text =
		"bbrules 1\nset T\n"
		"board B route=mp02.1\nboard D route=mp02.1\n"
		"nand n1 nand.id=c8:41\n";
	struct bb_rules r;
	struct bb_decision d;
	struct bb_facts f;

	CHECK(!bb_rules_load(&r, text, NULL), "load ambiguity rules");
	build(&samples[1], &f);
	bb_rules_decide(&r, &f, &d);
	CHECK(d.code == BB_DEC_AMBIGUOUS_BOARD, "ambiguous: %s", bb_decide_str(d.code));
	bb_rules_free(&r);

	{
		unsigned line = 0;

		CHECK(bb_rules_load(&r, "bbrules 1\nset T\nboard B colour=red\n", &line) && line == 3,
		      "unknown key rejected at line %u", line);
		CHECK(bb_rules_load(&r, "bbrules 2\nset T\n", &line), "wrong version rejected");
	}
}

static void test_env(void)
{
	struct bb_facts f;
	uint8_t *buf;
	size_t len;
	char json[4096];

	memset(&f, 0, sizeof(f));
	buf = fixture("field-env.bin", &len);
	if (!buf) {
		CHECK(0, "field-env.bin missing");
		return;
	}
	CHECK(!bb_facts_parse_env(&f, buf, len), "field env parses");
	CHECK(!strcmp(f.productname, "RT3000"), "productname %s", f.productname);
	CHECK(strlen(f.item_code) == 10 && !strncmp(f.item_code, "219801A2W3", 10), "item %s",
	      f.item_code);
	CHECK(bb_facts_json(&f, json, sizeof(json)) > 0, "json");
	/* Only the first 10 manucode characters may leave the device. */
	{
		const char *m = (const char *)memmem(buf, len, "manucode=", 9);

		CHECK(m && !strstr(json, m + 9), "full manucode not in json");
	}
	buf[100] ^= 1;
	memset(&f, 0, sizeof(f));
	CHECK(bb_facts_parse_env(&f, buf, len) && !f.env_crc_ok, "bad CRC detected");
	free(buf);
}

int main(void)
{
	const char *rules_path = getenv("BB_RULES");
	struct bb_rules r;
	unsigned line = 0;
	uint8_t *text;
	size_t len;

	fixtures = getenv("BB_FIXTURES");
	if (!fixtures || !rules_path) {
		printf("BB_FIXTURES and BB_RULES must be set\n");
		return 77;
	}
	text = load(rules_path, &len);
	if (!text || bb_rules_load(&r, (const char *)text, &line)) {
		printf("cannot load %s (line %u)\n", rules_path, line);
		return 1;
	}
	printf("  rule set %s, %u candidates\n", r.set, r.ncand);
	test_samples(&r);
	test_refusals(&r);
	test_ambiguity();
	test_env();
	bb_rules_free(&r);
	free(text);
	printf("%d checks, %d failures\n", checks, failures);
	return failures != 0;
}
